  void ShowChoices(){if(popup!=null){popup.Close();return;}if(!Enabled||Items.Count==0)return;OnDropDown(EventArgs.Empty);var form=new Form{FormBorderStyle=FormBorderStyle.None,ShowInTaskbar=false,StartPosition=FormStartPosition.Manual,BackColor=ModernTheme.Edge,Padding=new Padding(1),Font=Font};popup=form;choices=new StudioListBox{Dock=DockStyle.Fill,Font=Font,ItemHeight=ItemHeight,BorderStyle=BorderStyle.None};foreach(var item in Items)choices.Items.Add(GetItemText(item));form.Controls.Add(choices);choices.SelectedIndex=SelectedIndex;
   Action commit=()=>{int index=choices.SelectedIndex;if(index>=0&&index<Items.Count){SelectedIndex=index;OnSelectionChangeCommitted(EventArgs.Empty);}form.Close();};choices.MouseUp+=(s,e)=>{if(e.Button==MouseButtons.Left&&choices.IndexFromPoint(e.Location)>=0)commit();};choices.KeyDown+=(s,e)=>{if(e.KeyCode==Keys.Enter){e.Handled=e.SuppressKeyPress=true;commit();}else if(e.KeyCode==Keys.Escape){e.Handled=e.SuppressKeyPress=true;form.Close();}};
   var at=PointToScreen(new Point(0,Height));var work=Screen.FromControl(this).WorkingArea;int width=Math.Min(work.Width,Math.Max(Width,DropDownWidth)),height=Math.Min(work.Height,Math.Min(Math.Max(1,MaxDropDownItems),Items.Count)*ItemHeight+2);form.Bounds=new Rectangle(Math.Max(work.Left,Math.Min(at.X,work.Right-width)),at.Y+height<=work.Bottom?at.Y:Math.Max(work.Top,PointToScreen(Point.Empty).Y-height),width,height);form.Deactivate+=(s,e)=>form.Close();form.FormClosed+=(s,e)=>{popup=null;choices=null;OnDropDownClosed(EventArgs.Empty);if(!IsDisposed)Focus();form.Dispose();};ModernTheme.Apply(form);form.Show(FindForm());choices.Focus();}
